#include <flint/fmpq.h>
#include <flint/fmpq_mpoly.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cassert>
#include <chrono>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return*this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void readpoly(istream&in,Poly&p,bool keep=true){int n;in>>n;assert(in&&n>=0);fmpq_t q;fmpq_init(q);ulong ex[3];for(int k=0;k<n;k++){string s;in>>s>>ex[0]>>ex[1]>>ex[2];assert(in);if(keep){assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_mpoly_push_term_fmpq_ui(p.p,q,ex,ctx);}}if(keep){fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);}fmpq_clear(q);}
void writepoly(ostream&o,const Poly&p){int n=fmpq_mpoly_length(p.p,ctx);o<<n;fmpq_t q;fmpq_init(q);ulong ex[3];for(int k=0;k<n;k++){fmpq_mpoly_get_term_coeff_fmpq(q,p.p,k,ctx);fmpq_mpoly_get_term_exp_ui(ex,p.p,k,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1]<<' '<<ex[2];flint_free(s);}o<<'\n';fmpq_clear(q);}
long length(const vector<Poly>&r,int start=0){long n=0;for(int j=start;j<(int)r.size();j++)n+=fmpq_mpoly_length(r[j].p,ctx);return n;}
bool primitive(vector<Poly>&r,int start,int row,ostream&log){vector<int>ids;for(int j=start;j<(int)r.size();j++)if(!fmpq_mpoly_is_zero(r[j].p,ctx))ids.push_back(j);if(ids.empty())return true;sort(ids.begin(),ids.end(),[&](int i,int j){return fmpq_mpoly_length(r[i].p,ctx)<fmpq_mpoly_length(r[j].p,ctx);});Poly g=r[ids[0]],tmp;for(int j:ids){if(fmpq_mpoly_is_fmpq(g.p,ctx))break;assert(fmpq_mpoly_gcd(tmp.p,g.p,r[j].p,ctx));g=tmp;}if(!fmpq_mpoly_is_fmpq(g.p,ctx)){log<<"CONTENT row="<<row<<" start="<<start<<" terms="<<fmpq_mpoly_length(g.p,ctx)<<" degree="<<fmpq_mpoly_total_degree_si(g.p,ctx)<<'\n';for(int j:ids){assert(fmpq_mpoly_divides(tmp.p,r[j].p,g.p,ctx));r[j]=tmp;}}fmpq_t c;fmpq_init(c);fmpq_mpoly_get_term_coeff_fmpq(c,r[ids[0]].p,0,ctx);for(int j:ids)fmpq_mpoly_scalar_div_fmpq(r[j].p,r[j].p,c,ctx);fmpq_clear(c);return true;}
int main(int argc,char**argv){assert(argc==6);fmpq_mpoly_ctx_init(ctx,3,ORD_DEGREVLEX);{auto started=chrono::steady_clock::now();ifstream sel(argv[3]);int nr,nc;sel>>nr>>nc;assert(nr==35&&nc==40);vector<int>rows(nr),cols(nc);for(int&x:rows)sel>>x;for(int&x:cols)sel>>x;int nm;sel>>nm;assert(nm==91);vector<vector<pair<int,long>>>restriction(nm);for(auto&v:restriction){int n;sel>>n;while(n--){int j;long c;sel>>j>>c;v.push_back({j,c});}}
 vector<vector<Poly>>Q(20,vector<Poly>(35)),G(16,vector<Poly>(40));ifstream qi(argv[2]);int qn,qm;qi>>qn>>qm;assert(qn==20&&qm==35);for(auto&r:Q)for(auto&p:r)readpoly(qi,p);
 ifstream src(argv[1]);int n,m,k;src>>n>>m>>k;assert(n==57&&m==91&&k==57);Poly p,t;for(int i=0;i<57;i++)for(int j=0;j<91;j++){bool keep=i>=41&&!restriction[j].empty();fmpq_mpoly_zero(p.p,ctx);readpoly(src,p,keep);if(keep)for(auto[target,c]:restriction[j]){fmpq_mpoly_scalar_mul_si(t.p,p.p,c,ctx);fmpq_mpoly_add(G[i-41][target].p,G[i-41][target].p,t.p,ctx);}}
 vector<vector<Poly>>A(35,vector<Poly>(40));for(int i=0;i<35;i++)for(int j=0;j<40;j++){int r=rows[i],c=cols[j];if(r<20){if(c<35)A[i][j]=Q[r][c];}else A[i][j]=G[r-20][c];}Q.clear();G.clear();ofstream log(argv[4]);long total=0;for(auto&r:A)total+=length(r);log<<"INPUT_TERMS "<<total<<'\n';log.flush();if(total>500000){log<<"STOP_INITIAL_TERM_GUARD\n";return 2;}
 for(int i=0;i<35;i++)primitive(A[i],0,i,log);Poly x,y;bool finished=false;int steps=0;string status="running";
 for(int pivot=0;pivot<34;pivot++){int r=pivot;while(r<34&&fmpq_mpoly_is_zero(A[r][pivot].p,ctx))r++;assert(r<34);if(r!=pivot)swap(A[r],A[pivot]);Poly pp=A[pivot][pivot];for(int i=pivot+1;i<35;i++){if(fmpq_mpoly_is_zero(A[i][pivot].p,ctx))continue;Poly mult=A[i][pivot];for(int j=pivot+1;j<40;j++){fmpq_mpoly_mul(x.p,pp.p,A[i][j].p,ctx);fmpq_mpoly_mul(y.p,mult.p,A[pivot][j].p,ctx);fmpq_mpoly_sub(A[i][j].p,x.p,y.p,ctx);if(fmpq_mpoly_length(A[i][j].p,ctx)>150000){log<<"STOP_SINGLE_ENTRY_TERM_GUARD pivot="<<pivot<<" row="<<i<<" col="<<j<<'\n';return 2;}}fmpq_mpoly_zero(A[i][pivot].p,ctx);if(length(A[i],pivot+1)>800000){log<<"STOP_TEMP_ROW_TERM_GUARD\n";return 2;}primitive(A[i],pivot+1,i,log);}
  steps=pivot+1;long live=0;for(int i=pivot+1;i<35;i++)live+=length(A[i],pivot+1);double seconds=chrono::duration<double>(chrono::steady_clock::now()-started).count();log<<"STEP "<<steps<<" swap="<<r<<" pivot_terms="<<fmpq_mpoly_length(pp.p,ctx)<<" live_terms="<<live<<" lastrow_terms="<<length(A[34],pivot+1)<<" sec="<<seconds<<'\n';log.flush();if(live>1200000){log<<"STOP_LIVE_TERM_GUARD\n";return 2;}if(length(A[34],pivot+1)==0){status="all_six_zero_exact";finished=true;break;}if(seconds>55){log<<"STOP_NATIVE_55_SECONDS\n";return 2;}}
 if(!finished){bool nonzero=false;for(int j=34;j<40;j++)nonzero|=!fmpq_mpoly_is_zero(A[34][j].p,ctx);status=nonzero?"at_least_one_border_nonzero_exact":"all_six_zero_exact";}
 ofstream out(argv[5]);out<<status<<'\n'<<steps<<'\n';for(int j=34;j<40;j++){if(status=="all_six_zero_exact")out<<"0\n";else writepoly(out,A[34][j]);}log<<"FINAL "<<status<<'\n';log.flush();}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();return 0;}
